use openarch_api::Session;
use serde_json::{json,Value};
fn call(s:&mut Session,m:&str,p:Value)->Value{s.handle(m,&p).unwrap_or_else(|e|panic!("{m}: {e}"))}
fn setup()->(Session,Vec<u64>,u64){let mut s=Session::new();let info=call(&mut s,"doc_info",json!({}));let mut ids=vec![];for (n,length) in [4000,6000].into_iter().enumerate(){ids.push(call(&mut s,"add_wall",json!({"type_id":info["wall_types"][0]["id"],"level_id":info["levels"][0]["id"],"start":[0,n*4000],"end":[length,n*4000],"height_mm":2700}))["id"].as_u64().unwrap());}let schedule=call(&mut s,"add_schedule",json!({"category":"Walls","name":"IFC_WallData"}))["id"].as_u64().unwrap();let mut def=call(&mut s,"schedule_table",json!({"id":schedule}))["def"].clone();def["fields"]=json!([{"name":"Length","kind":"instance","heading":"Overall Length"},{"name":"Area","kind":"instance"},{"name":"Count","kind":"count"}]);def["itemize"]=json!(false);def["grand_totals"]=json!(true);def["ifc"]=json!({"enabled":true});call(&mut s,"set_schedule",json!({"id":schedule,"def":def}));(s,ids,schedule)}
#[test]
fn grouped_tables_export_individual_typed_values_and_mapping_names(){let(mut s,ids,schedule)=setup();let sets=call(&mut s,"ifc_schedule_properties",json!({"schedules":true}));assert_eq!(sets.as_array().unwrap().len(),2);for(i,id)in ids.iter().enumerate(){let p=sets.as_array().unwrap().iter().find(|p|p["element"]==*id).unwrap();let length=p["properties"].as_array().unwrap().iter().find(|p|p["name"]=="Overall Length").unwrap();assert_eq!(length["value"].as_f64(),Some(if i==0{4000.0}else{6000.0}));}
call(&mut s,"patch_schedule",json!({"id":schedule,"patch":{"ifc":{"explicit":true,"name":"Office Data","quantity_name":"Qto_Office","fields":[{"field":"Length","name":"Span","quantity":true},{"field":"Count","name":"Occurrences","unit":"integer"}]}}}));let sets=call(&mut s,"ifc_schedule_properties",json!({"schedules":true}));assert_eq!(sets.as_array().unwrap().len(),4);assert!(sets.as_array().unwrap().iter().any(|s|s["quantities"]==true&&s["name"]=="Qto_Office"));let path=std::env::temp_dir().join(format!("openarch-psets-{}.ifc",std::process::id()));call(&mut s,"export_ifc",json!({"path":path,"schedules":true}));let text=std::fs::read_to_string(&path).unwrap();assert!(text.contains("IFCELEMENTQUANTITY(")&&text.contains("IFCQUANTITYLENGTH('Span',$,$,4000.,$)"));assert!(text.contains("IFCINTEGER(1)"));let guids:Vec<_>=text.lines().filter(|l|l.contains("IFCPROPERTYSET(")||l.contains("IFCELEMENTQUANTITY(")||l.contains("IFCRELDEFINESBYPROPERTIES(")).map(str::to_string).collect();call(&mut s,"export_ifc",json!({"path":path,"schedules":true}));let again=std::fs::read_to_string(&path).unwrap();for line in guids{assert!(again.contains(&line));}std::fs::remove_file(path).unwrap();}
#[test]
fn export_filters_opt_in_hidden_fields_and_explicit_empty_mapping_are_respected(){let(mut s,_,id)=setup();assert!(call(&mut s,"ifc_schedule_properties",json!({})).as_array().unwrap().is_empty());call(&mut s,"patch_schedule",json!({"id":id,"patch":{"filters":[{"field":"Length","op":"greater","value":"5000"}],"fields":[{"name":"Length","kind":"instance"},{"name":"Area","kind":"instance","hidden":true}]}}));let sets=call(&mut s,"ifc_schedule_properties",json!({"schedules":true,"named_only":true}));assert_eq!(sets.as_array().unwrap().len(),1);assert_eq!(sets[0]["properties"].as_array().unwrap().len(),1);call(&mut s,"patch_schedule",json!({"id":id,"patch":{"ifc":{"explicit":true,"fields":[]}}}));assert!(call(&mut s,"ifc_schedule_properties",json!({"schedules":true})).as_array().unwrap().is_empty());}
#[test]
fn duplicate_property_names_and_text_quantities_are_refused(){let(mut s,_,id)=setup();assert!(s.handle("patch_schedule",&json!({"id":id,"patch":{"ifc":{"fields":[{"field":"Length","name":"Duplicate"},{"field":"Area","name":"Duplicate"}]}}})).is_err());assert!(s.handle("patch_schedule",&json!({"id":id,"patch":{"ifc":{"fields":[{"field":"Length","name":"Bad","quantity":true,"unit":"text"}]}}})).is_err());}
